WITH payload AS (SELECT $payload$[{"name":"北海道神宮","slug":"hokkaidojingu","prefecture":"北海道","prefecture_slug":"hokkaido","municipality":"札幌市","address":"北海道札幌市中央区宮ケ丘474番地","latitude":43.05447,"longitude":141.30779,"official_url":null,"history":"明治２年９月１日明治天皇の詔により北海道の開拓の守護神として東京の神祇官に開拓三神を御鎮斎になったのが北海道神宮の創祀であります。つづいて開拓長官ヒガシクセミチトミが神祇官より御霊代を戴き、開拓判官シマヨシタケが御霊代を奉じ札幌の地に入り明治４年５月に札幌神社と社名が定まり同年９月にこの円山の地に社殿を造営し鎮座されましたと伝えられています。伝承には諸説あります。","deities":["大国魂神","大那牟遅神","少彦名命","明治天皇"],"benefits":[],"lineages":["出雲系信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=1678","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"函館八幡宮","slug":"hakodate-hachimangu","prefecture":"北海道","prefecture_slug":"hokkaido","municipality":"函館市","address":"北海道函館市谷地頭町2番5号","latitude":41.753871815,"longitude":140.71000922,"official_url":null,"history":"文安２年（１４４５）河野政通が蝦夷地に渡来し現在の元町公園通りに館を築いたとき、その東南のすみに八幡社を立てたのが始まりといわれ、この八幡社は、一時赤川村（現市内赤川町）に移ったが、慶安年間（１６４８-１６５１）に再びもとの地に移した。寛政１１年（１７９９）幕府の東蝦夷地直轄にあたり、蝦夷奉行（後に箱館奉行と改め、翌年、奉行所庁舎が完成したと伝えられています。伝承には諸説あります。","deities":["応神天皇","住吉大神","金刀比羅大神"],"benefits":[],"lineages":["住吉信仰","八幡信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=1710","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"上川神社","slug":"kamikawa-jinja","prefecture":"北海道","prefecture_slug":"hokkaido","municipality":"旭川市","address":"北海道旭川市神楽岡公園2番地","latitude":43.752295033,"longitude":142.364740743,"official_url":null,"history":null,"deities":["天照皇大御神","大己貴大神","少彦名大神"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=1840","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"弘前八幡宮","slug":"hirosaki-hachimangu","prefecture":"青森県","prefecture_slug":"aomori","municipality":"弘前市","address":"青森県弘前市八幡町1-1-1","latitude":40.616098047,"longitude":140.479367371,"official_url":null,"history":"弘前八幡宮は、慶長１７年（１６１２）二代藩主信牧公の治世、大浦郷八幡（現岩木町八幡）から、それまで大浦城の鎮守と崇めてきた八幡宮をこの地に遷座いたしました。古伝によりますと、信牧公が霊夢によって城の東北地方に高岡と呼ぶ霊地をト定したといわれ、これが現社地でありますと伝えられています。伝承には諸説あります。","deities":["誉田別命","息長足姫命","比売大神"],"benefits":[],"lineages":["八幡信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2550","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"盛岡八幡宮","slug":"morioka-hachimangu","prefecture":"岩手県","prefecture_slug":"iwate","municipality":"盛岡市","address":"岩手県盛岡市八幡町13-1","latitude":39.69530635,"longitude":141.164009492,"official_url":null,"history":"秋祭 康平５年（１０６２）前九年の役に際し、陸奥鎮守府将軍源頼義・義家父子が、奥州安倍一族（貞任・宗任）平定のため山城国男山八幡大神を不来方（こずかた）の丘陵の地（現盛岡市岩手公園・元の盛岡城）に御勧請、必勝武運を祈願したのが創祀と伝えられ、後世鳩森八幡社と称し、豪族の日戸氏が奉斎敬事に当たっていたという。その後源頼朝公の義経追討に関る奥州平定に際し、南部の荘（山梨県）より参陣した初代南部光行公は大いに軍功をたて、論功行賞により糠部五郡を拝領し、三戸に居城、八幡大神を祀ったと伝えられています。伝承には諸説あります。","deities":["品陀和気命"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2396","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"志和稲荷神社","slug":"shiwa-inari-jinja","prefecture":"岩手県","prefecture_slug":"iwate","municipality":"紫波郡紫波町","address":"岩手県紫波郡紫波町升沢字前平17番地","latitude":39.558979628,"longitude":141.077875162,"official_url":null,"history":"御裳裾を流れる滝名川の清流は心を洗い、千古の老杉が欝蒼と繁茂する霊場に鎮まります志和稲荷神社は、千年の歴史を伝える東北屈指の古社にして、生活生業万般に亘り広大無辺の御神徳あらたかな三柱の貴神を奉祭し、その連綿と続く歴史の中で人々の尊崇をあつめ、特に天喜五年に鎮守府将軍源頼義が社殿を再興したのを初めとして、平泉文化酣なわ頃は樋爪氏、中世には斯波氏、近世には南部藩主代々に亘り社領の寄進や社殿の造営を行い、天保五・六年には参詣街道を開削するなどして敬神の誠をつくしてこられましたと伝えられています。伝承には諸説あります。","deities":["宇迦之御魂大神","猿田彦大神","大宮能売大神"],"benefits":[],"lineages":["稲荷信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2425","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"早池峰神社","slug":"haya-ikemine-jinja","prefecture":"岩手県","prefecture_slug":"iwate","municipality":"遠野市","address":"岩手県遠野市附馬牛町上附馬牛第19地割81番地","latitude":39.4755737,"longitude":141.5092865,"official_url":null,"history":"当神社は遠野三山の主峰早池峰山の山霊を祀る。草創は大同元年（８０７）３月８日猟師四角藤蔵（後に始閣と定む）が早池峰山頂に於いて霊容を拝して発心、山道を拓いてその年の６月１８日山頂に７尺有余の宮を創建して早池峯大権現を祀ったのがこの社の始まりと伝えられていると伝えられています。伝承には諸説あります。","deities":["瀬織津姫命"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2502","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/781191803","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"竹駒神社","slug":"takekoma-jinja","prefecture":"宮城県","prefecture_slug":"miyagi","municipality":"岩沼市","address":"宮城県岩沼市稲荷町1-1","latitude":38.1049802,"longitude":140.8619439,"official_url":null,"history":"竹駒稲荷神社は古くから日本三稲荷の一つに数えられる極めて霊験のあらたかな神社とたたえられ、衣・食・住の守護神であられる倉稲魂神・保食神・稚産神の三柱の神々をお祀り申し上げております。御創建は人皇五十四代仁明天皇の承和９年、（西暦８４２）で小倉百人一首にも名を連ねる参議小野篁卿が陸奥守として御着任の際、東北開拓・産業開発の大神として御創建され、古くは平泉藤原三代、降っては仙台藩主伊達家歴代の尊崇頻る厚く、特に大衆を慈しまれる神として崇められておりますと伝えられています。伝承には諸説あります。","deities":["倉稲魂神"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2109","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/240601719","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"秋田神社","slug":"akita-jinja","prefecture":"秋田県","prefecture_slug":"akita","municipality":"横手市","address":"秋田県横手市城山町4","latitude":39.319692838,"longitude":140.570310203,"official_url":null,"history":null,"deities":["佐竹義宣","佐竹義尭"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=64835","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"唐松神社","slug":"karamatsu-jinja","prefecture":"秋田県","prefecture_slug":"akita","municipality":"大仙市","address":"秋田県大仙市協和境字下台94","latitude":39.61032948,"longitude":140.320883554,"official_url":null,"history":null,"deities":["軻具突命","息気長足姫命","豊宇気姫命","高皇霊命","神皇霊命"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=64783","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"上杉神社","slug":"uesugi-jinja","prefecture":"山形県","prefecture_slug":"yamagata","municipality":"米沢市","address":"山形県米沢市丸の内1-4-13(南堀端町36)","latitude":37.909289536,"longitude":140.104096078,"official_url":null,"history":"御祭神上杉謙信 天正６年（１５７８）３月１３日、戦国の名将上杉謙信公が越後の春日山城に４９才で急逝された時、その遺骸を城中不識庵に仏式を以て鎮祭されたのであるが、二代景勝公が会津を経て米沢に移封されるに当り、祠堂を米沢城内に移して仏祭を厳修し爾来２６０年に及んだ。明治の世を迎え祠堂のまま神祭に改め、米沢藩中興の名君鷹山公を合祀して上杉神社と称し県社に列し、同９年には新たに神殿成り初めて遷座祭を行なうと伝えられています。伝承には諸説あります。","deities":["上杉謙信"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2717","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"湯殿山神社","slug":"yudonosan-jinja","prefecture":"山形県","prefecture_slug":"yamagata","municipality":"山形市","address":"山形県山形市旅篭町3-4-6","latitude":38.2573952,"longitude":140.3400692,"official_url":null,"history":"明治９年初代山形県令三島通庸は、県庁舎の建設の地を山形市旅籠町の万日河原と定め、その地鎮祭を行うにあたり、田川郡湯殿山に鎮座する国弊小社湯殿山本宮の口の宮本道寺湯殿山神社より分霊を勧請して旅籠町雁島に祭った。翌明治１０年１１月正面三層楼の洋風の県庁舎が完成開庁し、これに引き続き師範学校、警察本部、郡役所、銀行等々次々と建ち、雁島の湯殿山神社は、県庁のみならず山形中心部の鎮守と仰がれるようになったと伝えられています。伝承には諸説あります。","deities":["大山祇命","大名持命","少彦名命"],"benefits":[],"lineages":["出雲系信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2661","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/909125582","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"伊佐須美神社","slug":"isa-sumi-jinja","prefecture":"福島県","prefecture_slug":"fukushima","municipality":"会津若松市","address":"福島県会津若松市神指町大字南四合字深川乙59","latitude":37.49276231,"longitude":139.899995564,"official_url":null,"history":null,"deities":["伊邪那岐命","伊邪那美命"],"benefits":[],"lineages":["熊野信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=70034","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"相馬中村神社","slug":"soma-nakamura-jinja","prefecture":"福島県","prefecture_slug":"fukushima","municipality":"相馬市","address":"福島県相馬市沖ノ内字北町140・141","latitude":37.797312995,"longitude":140.913017255,"official_url":null,"history":"旧藩主家をはじめ相馬全領の総鎮守として庶民の御信仰を集めてまいりました当神社は、かっては「相馬妙見大明神」の旧称号で、一般には「相馬のオミョウケンサマ」と呼ばれ親しまれてまいりました。現在御祭神として天之御中主神をお祀りしておりますと伝えられています。伝承には諸説あります。","deities":["天御中主神"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2353","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"石都々古和気神社","slug":"ishi-to-ko-waki-jinja","prefecture":"福島県","prefecture_slug":"fukushima","municipality":"石川郡石川町","address":"福島県石川郡石川町字下泉296","latitude":37.144964654,"longitude":140.451040073,"official_url":null,"history":null,"deities":["誉田別命","大国主命"],"benefits":[],"lineages":["八幡信仰","出雲系信仰"],"sources":[{"name":"全国一の宮巡拝会「全国一の宮一覧」","url":"http://ichinomiya-junpai.jp/alllist/%e5%8c%97%e6%b5%b7%e9%81%93%e3%83%bb%e6%9d%b1%e5%8c%97/","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"岩木山神社","slug":"iwakiyama-jinja","prefecture":"青森県","prefecture_slug":"aomori","municipality":"弘前市","address":"青森県弘前市百沢字寺沢27","latitude":40.6208899,"longitude":140.3416538,"official_url":null,"history":"秋祭 当社は昔から「お岩木さま」「お山」と親しんで呼ばれ、陸奥津軽の開拓の神、農海産物の守護神、また祖霊の座すところとして崇められてまいりました。神山・霊山である岩木山は津軽全土から仰望せられ、人々に慈しみの徳を授けたまい、郷土人の生活と心のよりどころでありますと伝えられています。伝承には諸説あります。","deities":["顕国魂神","多都比姫神","大山祇神","坂上刈田麿","宇賀能売神"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2556","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/825426970","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"櫛引八幡宮","slug":"kushibiki-hachimangu","prefecture":"青森県","prefecture_slug":"aomori","municipality":"八戸市","address":"青森県八戸市八幡字八幡丁3-2","latitude":40.4896732,"longitude":141.4346687,"official_url":null,"history":"本宮は大同年中（８０６年頃）、坂上田村麿が八幡大明神をまつり仁安元年（１１６６）新羅三郎義光の四代の孫、加賀美次郎遠光が甲斐の国（山梨県）南部の郷に八幡大明神をおまつりしたことに始まります。その後、遠光の三男南部三郎光行が文治の役（１１８９）に戦功をあげ、陸奥の国糠部五郡（現在の二戸郡、九戸郡、三戸郡、上北郡、下北郡）を賜わり、建久２年（１１９１）この地方に来て、十和田滝ノ沢に仮宮を営み、貞応元年（１２２２）に現在の地に、新しい社殿を造り、滝ノ沢からおうつしして、祀ったのが由来であると伝えられています。伝承には諸説あります。","deities":["誉田別尊"],"benefits":[],"lineages":["八幡信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2634","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/755356210","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"猿賀神社","slug":"saruka-jinja","prefecture":"青森県","prefecture_slug":"aomori","municipality":"平川市","address":"青森県平川市猿賀石林175","latitude":40.6164807,"longitude":140.5642614,"official_url":null,"history":"古典（日本書紀）によれば田道命は「仁徳天皇５５年（西暦３６７）勅命を受けて北夷の反乱を平定のため東北地方に兵を進めたが、戦利あらず、伊寺の水門で戦死なさる。後に大蛇の姿となって暴夷を平定した」とあると伝えられています。伝承には諸説あります。","deities":["上毛野君田道命"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2590","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/382249131","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"秋田諏訪宮","slug":"akita-suwa-miya","prefecture":"秋田県","prefecture_slug":"akita","municipality":"仙北郡美郷町","address":"秋田県仙北郡美郷町六郷字本道町20","latitude":39.4237546,"longitude":140.5430361,"official_url":null,"history":null,"deities":["建御名方富命","八坂刀女命"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=64711","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/815641399","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"福島稲荷神社","slug":"fukushima-inari-jinja","prefecture":"福島県","prefecture_slug":"fukushima","municipality":"福島市","address":"福島県福島市宮町1-29","latitude":37.7555722,"longitude":140.4687723,"official_url":null,"history":"福島稻荷神社（祭神豊受比賣命）の由緒は社伝によれば、第６６代一条天皇の永延元年（９８７）、当時朝廷に重用された陰陽道博士従五位下阿倍晴明が詔を奉じて奥羽下向の際、吹島の里（後に福島と改む）にさしかかり、西には吾妻山が空にそびえ、北には信夫山が平原の中より屹然として突出し、南は阿武隈川の清流洋々として東流し、山水の風致、自然の景勝に目をみはるのみならず地味肥沃にして農耕に適し、将来大いに有望な地相であるとしてここに社を建て、衣食住を司る豊受比賣大神（伊勢神宮の外宮の御祭神）を勧請し、此の里の総鎮守としたことに始まりますと伝えられています。伝承には諸説あります。","deities":["豊受比売命"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2196","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/node/2036166124","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"太平山三吉神社","slug":"futo-hirayama-sankichi-jinja","prefecture":"秋田県","prefecture_slug":"akita","municipality":"秋田市","address":"秋田県秋田市太平山谷字谷山21","latitude":39.7262492,"longitude":140.144072,"official_url":null,"history":"参拝のしおり 霊峰太平山に祀る太平山三吉神社は、今を去る１、３００余年前天武天皇の白鳳２年５月に、役の行者小角の創建にかかり、桓武天皇の延暦２０年征夷大将軍坂上田村麻呂が、東夷征討のみぎり、戦勝を祈願して堂宇を建立するなど、古代王朝の頃より、勝利成功、事業繁栄の守護神として、その霊験顕著なるを以て知られるところであり、その奉納せる鏑は今に伝えて神宝とされ、その他神鏡等数品が安置されております。秋田藩佐竹累代の藩主また崇敬篤く、第８代曙山義敦公はその現里宮の地の風光明媚なる地を賞して別墅を築き雪見御殿としたのでありますと伝えられています。伝承には諸説あります。","deities":["大名貴大神","少彦名大神","三吉霊神"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2844","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/way/776420037","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"鳥海山大物忌神社","slug":"toriumi-yamadai-monoimi-jinja","prefecture":"山形県","prefecture_slug":"yamagata","municipality":"飽海郡遊佐町","address":"山形県飽海郡遊佐町大字吹浦字布倉1","latitude":39.097694444,"longitude":140.048694444,"official_url":null,"history":"欽明天皇２５年（１４００余年前）鳥海山上に鎮座され貞観４年官社に列し国家の祀典に預り延喜の制には吹浦に鎮座し給ふ月山神社と共に名神大社に班し後出羽国一宮としてその撰に預り朝野の尊信を享けてきた。特に歴代天皇の崇敬篤く八幡太郎義家の戦勝祈願、北畠顕信の土地寄進、鎌倉幕府や庄内藩主の社殿の造修等代々の武将にも篤く崇敬されてきたと伝えられています。伝承には諸説あります。","deities":["大物忌大神","月山神"],"benefits":[],"lineages":["出羽三山信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2810","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://ja.wikipedia.org/wiki/%E9%B3%A5%E6%B5%B7%E5%B1%B1%E5%A4%A7%E7%89%A9%E5%BF%8C%E7%A5%9E%E7%A4%BE","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"鳥海山大物忌神社(蕨岡口之宮)","slug":"toriumi-yamadai-monoimi-jinja-warabioka-kuchino-miya","prefecture":"山形県","prefecture_slug":"yamagata","municipality":"飽海郡遊佐町","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡51","latitude":38.9971611,"longitude":139.9448388,"official_url":"http://ichinomiya-junpai.jp/alllist/%e5%8c%97%e6%b5%b7%e9%81%93%e3%83%bb%e6%9d%b1%e5%8c%97/","history":"旧山形県の一之宮として奉斎されてきたと伝えられています。個々の伝承には諸説あります。","deities":[],"benefits":["五穀豊穣","海上安全","厄除開運"],"lineages":[],"sources":[{"name":"全国一の宮巡拝会「全国一の宮一覧」","url":"http://ichinomiya-junpai.jp/alllist/%e5%8c%97%e6%b5%b7%e9%81%93%e3%83%bb%e6%9d%b1%e5%8c%97/","source_type":"official_site","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/node/4457814291","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"出雲大神宮","slug":"izumo-daijingu-fukushima","prefecture":"福島県","prefecture_slug":"fukushima","municipality":"福島市","address":"福島県福島市清水町字西裏89","latitude":37.701161965,"longitude":140.461298894,"official_url":null,"history":"神階 文化１４年６月「大神宮」と宣下。旧社格 村社と伝えられています。伝承には諸説あります。","deities":["大己貴命","素盞嗚命"],"benefits":[],"lineages":["出雲系信仰","祇園信仰"],"sources":[{"name":"全国一の宮巡拝会「全国一の宮一覧」","url":"http://ichinomiya-junpai.jp/alllist/%e8%bf%91%e7%95%bf/","source_type":"other","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/?mlat=37.701161965&mlon=140.461298894&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"倭文神社","slug":"shizu-jinja-iwate","prefecture":"岩手県","prefecture_slug":"iwate","municipality":"遠野市","address":"岩手県遠野市土渕町第18地割174番地","latitude":39.348915372,"longitude":141.554802292,"official_url":null,"history":"当神社の例祭日は旧暦７月２５日であったが、現在は８月２０日に行っている。勧請年月日は明らかではないが、昔から「お文珠様」と呼ばれていて、例祭には学童たちが習字を奉納して筆写の上達を祈ったと伝えられています。伝承には諸説あります。","deities":["天照皇大神"],"benefits":[],"lineages":["伊勢信仰"],"sources":[{"name":"全国一の宮巡拝会「全国一の宮一覧」","url":"http://ichinomiya-junpai.jp/alllist/%e4%b8%ad%e5%9b%bd/","source_type":"other","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/?mlat=39.348915372&mlon=141.554802292&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"宇倍神社","slug":"bai-jinja-fukushima","prefecture":"福島県","prefecture_slug":"fukushima","municipality":"郡山市","address":"福島県郡山市喜久田町堀之内字向原5","latitude":37.441849348,"longitude":140.346220195,"official_url":null,"history":null,"deities":["武内宿禰命"],"benefits":[],"lineages":[],"sources":[{"name":"全国一の宮巡拝会「全国一の宮一覧」","url":"http://ichinomiya-junpai.jp/alllist/%e4%b8%ad%e5%9b%bd/","source_type":"other","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/?mlat=37.441849348&mlon=140.346220195&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"氷川神社","slug":"hikawajinja","prefecture":"北海道","prefecture_slug":"hokkaido","municipality":"新冠郡新冠町","address":"北海道新冠郡新冠町字東町4番地1","latitude":42.3572934,"longitude":142.3195103,"official_url":null,"history":"祭神⇒須佐之男命。伊弉諾尊、伊弉冉尊の御子と伝えられています。伝承には諸説あります。","deities":["須佐之男命"],"benefits":[],"lineages":["祇園信仰"],"sources":[{"name":"全国一の宮巡拝会「全国一の宮一覧」","url":"http://ichinomiya-junpai.jp/alllist/%e9%96%a2%e6%9d%b1/","source_type":"other","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/?mlat=42.3572934&mlon=142.3195103&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"浅間神社","slug":"asama-jinja","prefecture":"北海道","prefecture_slug":"hokkaido","municipality":"松前郡松前町","address":"北海道松前郡松前町字静浦343番地","latitude":41.4868615,"longitude":140.0237831,"official_url":null,"history":"往昔当村民の多くは農山業に従事し山神尊崇の念篤く隣村赤神神社祭神が大山祗命なるを以って、その御子木花佐久也姫命を奉斎することに村中一決し、元禄２年上雨石崎に社殿を建立し勧請奉斎せるものなりと云い伝う。明治９年村社に列格、同４１年７月２５日氏子石山常作より土地の寄附があり大正２年３月２０日社殿移転並びに改築の儀出願許可を得て、移転改築落成奉遷せりと伝えられています。伝承には諸説あります。","deities":["木花佐久也比売命"],"benefits":[],"lineages":[],"sources":[{"name":"全国一の宮巡拝会「全国一の宮一覧」","url":"http://ichinomiya-junpai.jp/alllist/%e7%94%b2%e4%bf%a1%e8%b6%8a/","source_type":"other","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/?mlat=41.4868615&mlon=140.0237831&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"住吉神社","slug":"sumiyoshi-jinja-hokkaido","prefecture":"北海道","prefecture_slug":"hokkaido","municipality":"小樽市","address":"北海道小樽市住ノ江2丁目5番1号","latitude":43.1826667,"longitude":141.002712,"official_url":null,"history":"元治元年、箱舘八幡宮神主菊地大蔵重賢より「オタルナイ」「タカシマ」両場所の総鎮守として、勧請の儀を箱舘奉行所に出願し、社寺奉行所掛合済の上、慶應元年６月の通り「オタルナイ」運上屋最寄の地へ、住吉大神勧請奉祀する事を許され、翌慶應２年に至り、本陣付近に適当なる社地下付方を「オタルナイ」御用所に出願す。幕府は「オタルナイ」役所詰の幕吏に命じ、小樽入港の請船に賊役し、本陣下の汀渚に埋立を行い、この地を相して住吉大神の神社造営を許可せりと伝えられています。伝承には諸説あります。","deities":["底筒男神","中筒男神","表筒男神","息長帯姫命"],"benefits":[],"lineages":[],"sources":[{"name":"全国一の宮巡拝会「全国一の宮一覧」","url":"http://ichinomiya-junpai.jp/alllist/%e4%b8%ad%e5%9b%bd/","source_type":"other","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/?mlat=43.1826667&mlon=141.002712&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"鹽竈神社","slug":"shiogama-jinja","prefecture":"宮城県","prefecture_slug":"miyagi","municipality":"塩竈市","address":"宮城県塩竈市一森山1-1","latitude":38.318946,"longitude":141.012646,"official_url":"https://shiogamajinja.jp/","history":null,"deities":["塩土老翁神","武甕槌命","経津主命"],"benefits":[],"lineages":["鹿島信仰"],"sources":[{"name":"鹽竈神社 公式サイト","url":"https://shiogamajinja.jp/","source_type":"official_site","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/?mlat=38.318946&mlon=141.012646&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"大崎八幡宮","slug":"osaki-hachimangu","prefecture":"宮城県","prefecture_slug":"miyagi","municipality":"仙台市","address":"宮城県仙台市青葉区八幡4丁目6-1","latitude":38.2716378,"longitude":140.8448528,"official_url":"https://www.oosaki-hachiman.or.jp/","history":null,"deities":["応神天皇"],"benefits":[],"lineages":["八幡信仰"],"sources":[{"name":"大崎八幡宮 公式サイト","url":"https://www.oosaki-hachiman.or.jp/","source_type":"official_site","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/?mlat=38.2716378&mlon=140.8448528&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"出羽三山神社","slug":"dewa-sanzan-jinja","prefecture":"山形県","prefecture_slug":"yamagata","municipality":"鶴岡市","address":"山形県鶴岡市羽黒町手向手向7","latitude":38.706602039145,"longitude":139.963986249624,"official_url":"http://www.dewasanzan.jp/","history":null,"deities":["月読命","宇迦之御魂神","大山祇神","大国主神","少彦名神"],"benefits":[],"lineages":["出羽三山信仰","出雲系信仰","稲荷信仰"],"sources":[{"name":"出羽三山神社 公式サイト","url":"http://www.dewasanzan.jp/","source_type":"official_site","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/?mlat=38.706602039145&mlon=139.963986249624&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]}]$payload$::jsonb AS value), incoming AS (SELECT * FROM jsonb_to_recordset((SELECT value FROM payload)) AS x(name text,slug text,prefecture text,prefecture_slug text,municipality text,address text,latitude double precision,longitude double precision,official_url text,history text,deities text[],benefits text[],lineages text[],sources jsonb)), pref_upsert AS (INSERT INTO public.prefectures(name,slug) SELECT DISTINCT prefecture,prefecture_slug FROM incoming ON CONFLICT (slug) DO UPDATE SET name=excluded.name RETURNING id,name), municipality_upsert AS (INSERT INTO public.municipalities(prefecture_id,name) SELECT DISTINCT p.id,i.municipality FROM incoming i JOIN pref_upsert p ON p.name=i.prefecture ON CONFLICT (prefecture_id,name) DO UPDATE SET name=excluded.name RETURNING id,prefecture_id,name), shrine_upsert AS (INSERT INTO public.shrines(name,slug,prefecture_id,municipality_id,address,location,official_url,history,is_published) SELECT i.name,i.slug,p.id,m.id,i.address,ST_SetSRID(ST_MakePoint(i.longitude,i.latitude),4326)::geography,i.official_url,i.history,true FROM incoming i JOIN pref_upsert p ON p.name=i.prefecture JOIN municipality_upsert m ON m.prefecture_id=p.id AND m.name=i.municipality ON CONFLICT (slug) DO UPDATE SET name=excluded.name,prefecture_id=excluded.prefecture_id,municipality_id=excluded.municipality_id,address=excluded.address,location=excluded.location,official_url=COALESCE(excluded.official_url,public.shrines.official_url),history=COALESCE(excluded.history,public.shrines.history),is_published=true,updated_at=now() RETURNING id,slug), source_rows AS (SELECT DISTINCT i.slug,s.name,s.url,s.source_type,s.field_name,s.notes FROM incoming i CROSS JOIN LATERAL jsonb_to_recordset(i.sources) AS s(name text,url text,source_type text,field_name text,notes text) WHERE s.url IS NOT NULL), source_upsert AS (INSERT INTO public.sources(name,url,source_type,last_verified_at,notes) SELECT s.name,s.url,s.source_type::public.source_type,DATE '2026-10-01',s.notes FROM (SELECT DISTINCT name,url,source_type,notes FROM source_rows) s WHERE NOT EXISTS (SELECT 1 FROM public.sources old WHERE old.name=s.name AND old.url=s.url) RETURNING id,name,url), source_records AS (SELECT id,name,url FROM source_upsert UNION ALL SELECT old.id,old.name,old.url FROM public.sources old JOIN (SELECT DISTINCT name,url FROM source_rows) x ON x.name=old.name AND x.url=old.url), source_links AS (INSERT INTO public.shrine_sources(shrine_id,source_id,field_name) SELECT DISTINCT sh.id,src.id,s.field_name FROM source_rows s JOIN shrine_upsert sh ON sh.slug=s.slug JOIN source_records src ON src.name=s.name AND src.url=s.url ON CONFLICT (shrine_id,source_id) DO UPDATE SET field_name=COALESCE(excluded.field_name,public.shrine_sources.field_name) RETURNING shrine_id), deity_links AS (INSERT INTO public.shrine_deities(shrine_id,deity_id,role,display_order) SELECT DISTINCT sh.id,d.id,'principal'::public.shrine_deity_role,0 FROM incoming i JOIN shrine_upsert sh ON sh.slug=i.slug CROSS JOIN LATERAL unnest(COALESCE(i.deities,ARRAY[]::text[])) raw(name) JOIN LATERAL (SELECT de.id FROM public.deities de WHERE de.name=raw.name OR raw.name=ANY(de.aliases) ORDER BY (de.name=raw.name) DESC,de.slug LIMIT 1) d ON true ON CONFLICT (shrine_id,deity_id) DO UPDATE SET role='principal'::public.shrine_deity_role RETURNING shrine_id,deity_id), shrine_lineage_links AS (INSERT INTO public.shrine_lineages(shrine_id,lineage_id) SELECT DISTINCT sh.id,l.id FROM incoming i JOIN shrine_upsert sh ON sh.slug=i.slug CROSS JOIN LATERAL unnest(COALESCE(i.lineages,ARRAY[]::text[])) ln(name) JOIN public.lineages l ON l.name=ln.name ON CONFLICT DO NOTHING RETURNING shrine_id,lineage_id), shrine_benefit_links AS (INSERT INTO public.shrine_benefits(shrine_id,benefit_id,description) SELECT DISTINCT sh.id,b.id,'出典に記された信仰上の願意の一例です。宗教的効能や結果を保証するものではありません。' FROM incoming i JOIN shrine_upsert sh ON sh.slug=i.slug CROSS JOIN LATERAL unnest(COALESCE(i.benefits,ARRAY[]::text[])) bn(name) JOIN public.benefits b ON b.name=bn.name ON CONFLICT (shrine_id,benefit_id) DO UPDATE SET description=excluded.description RETURNING shrine_id,benefit_id), inferred_deity_benefits AS (INSERT INTO public.deity_benefits(deity_id,benefit_id) SELECT DISTINCT dl.deity_id,sb.benefit_id FROM deity_links dl JOIN shrine_benefit_links sb ON sb.shrine_id=dl.shrine_id ON CONFLICT DO NOTHING RETURNING deity_id,benefit_id) SELECT jsonb_build_object('shrines_upserted',(SELECT count(*) FROM shrine_upsert),'sources_added',(SELECT count(*) FROM source_upsert),'source_links',(SELECT count(*) FROM source_links),'deity_links',(SELECT count(*) FROM deity_links),'lineage_links',(SELECT count(*) FROM shrine_lineage_links),'benefit_links',(SELECT count(*) FROM shrine_benefit_links),'deity_benefit_links',(SELECT count(*) FROM inferred_deity_benefits)) AS result;
